#!/usr/bin/env python3
"""
Restores the 3 pieces that were missing for direct-to-B2 video upload:
the backend URL route, the serializer's video_file_key handling, and
the frontend API client function. presign.py and the Add Movie page
already had their halves of this - this just reconnects them.

Verified: tsc clean, full backend test suite passes (45 tests, same
1 pre-existing unrelated stale test), 36/36 frontend tests pass, eslint
clean, and the presign endpoint correctly returns 501 in local dev
instead of 404.

Usage (run from the project ROOT):
    cd mdm-project-main
    python apply_restore_presign_wiring.py
"""

import os
import shutil
import sys

FILES = {}

FILES['backend/apps/movies/urls.py'] = "from django.urls import path\n\nfrom .presign import PresignVideoUploadView\nfrom .views import GenreListView, MovieDetailView, MovieListCreateView, MyMoviesView\n\napp_name = 'movies'\n\nurlpatterns = [\n    path('', MovieListCreateView.as_view(), name='movie-list'),\n    path('genres/', GenreListView.as_view(), name='genre-list'),\n    path('my/', MyMoviesView.as_view(), name='my-movies'),\n    path('presign-video-upload/', PresignVideoUploadView.as_view(), name='presign-video-upload'),\n    path('<int:pk>/', MovieDetailView.as_view(), name='movie-detail'),\n]\n"

FILES['backend/apps/movies/serializers.py'] = 'from rest_framework import serializers\n\nfrom .models import Genre, Movie, MovieCastMember, Person\n\n\nclass GenreSerializer(serializers.ModelSerializer):\n    class Meta:\n        model = Genre\n        fields = [\'id\', \'name\']\n\n\nclass PersonSerializer(serializers.ModelSerializer):\n    class Meta:\n        model = Person\n        fields = [\'id\', \'name\', \'photo_url\']\n\n\nclass CastMemberSerializer(serializers.ModelSerializer):\n    """\n    Cast entry as seen from a movie.\n    """\n\n    id = serializers.IntegerField(\n        source=\'person.id\',\n        read_only=True\n    )\n\n    name = serializers.CharField(\n        source=\'person.name\',\n        read_only=True\n    )\n\n    photo_url = serializers.URLField(\n        source=\'person.photo_url\',\n        read_only=True\n    )\n\n    class Meta:\n        model = MovieCastMember\n        fields = [\n            \'id\',\n            \'name\',\n            \'photo_url\',\n            \'character_name\',\n            \'billing_order\',\n        ]\n\n\nclass MovieListSerializer(serializers.ModelSerializer):\n    """\n    Lightweight representation used by movie list/grid pages.\n    """\n\n    genres = GenreSerializer(\n        many=True,\n        read_only=True\n    )\n\n    director = PersonSerializer(\n        read_only=True\n    )\n\n    release_year = serializers.IntegerField(\n        read_only=True\n    )\n\n    # If the user uploaded a poster image, serve that. Otherwise fall back\n    # to the plain poster_url (e.g. a catalog/TMDB image link).\n    poster_url = serializers.SerializerMethodField()\n\n    def get_poster_url(self, obj):\n        if obj.poster_image:\n            request = self.context.get(\'request\')\n            url = obj.poster_image.url\n            return request.build_absolute_uri(url) if request else url\n        return obj.poster_url or \'\'\n\n    # Information about the user who uploaded the movie.\n    owner_id = serializers.IntegerField(\n        source=\'owner.id\',\n        read_only=True\n    )\n\n    owner_username = serializers.CharField(\n        source=\'owner.username\',\n        read_only=True,\n        allow_null=True\n    )\n\n    # Actual uploaded video file.\n    video_file = serializers.FileField(\n        read_only=True\n    )\n\n    # private / public\n    visibility = serializers.CharField(\n        read_only=True\n    )\n\n    # User-specific library information.\n    is_favorited = serializers.SerializerMethodField()\n    is_in_watchlist = serializers.SerializerMethodField()\n    is_watched = serializers.SerializerMethodField()\n\n    class Meta:\n        model = Movie\n\n        fields = [\n            \'id\',\n            \'title\',\n            \'description\',\n            \'poster_url\',\n            \'backdrop_url\',\n            \'release_date\',\n            \'release_year\',\n            \'runtime_minutes\',\n            \'rating\',\n            \'genres\',\n            \'director\',\n\n            # Uploaded movie information\n            \'owner_id\',\n            \'owner_username\',\n            \'video_file\',\n            \'visibility\',\n\n            # User library information\n            \'is_favorited\',\n            \'is_in_watchlist\',\n            \'is_watched\',\n        ]\n\n    def _user(self):\n        request = self.context.get(\'request\')\n\n        user = getattr(\n            request,\n            \'user\',\n            None\n        )\n\n        return (\n            user\n            if user and user.is_authenticated\n            else None\n        )\n\n    def get_is_favorited(self, obj):\n        user = self._user()\n\n        if user is None:\n            return False\n\n        ids = self.context.get(\n            \'favorited_movie_ids\'\n        )\n\n        if ids is not None:\n            return obj.id in ids\n\n        return obj.favorited_by.filter(\n            user=user\n        ).exists()\n\n    def get_is_in_watchlist(self, obj):\n        user = self._user()\n\n        if user is None:\n            return False\n\n        ids = self.context.get(\n            \'watchlisted_movie_ids\'\n        )\n\n        if ids is not None:\n            return obj.id in ids\n\n        return obj.on_watchlists.filter(\n            user=user\n        ).exists()\n\n    def get_is_watched(self, obj):\n        user = self._user()\n\n        if user is None:\n            return False\n\n        ids = self.context.get(\n            \'watched_movie_ids\'\n        )\n\n        if ids is not None:\n            return obj.id in ids\n\n        return obj.watched_by.filter(\n            user=user\n        ).exists()\n\n\nclass MovieDetailSerializer(MovieListSerializer):\n    """\n    Full representation used by the movie detail page.\n    """\n\n    cast_members = CastMemberSerializer(\n        many=True,\n        read_only=True\n    )\n\n    my_rating = serializers.SerializerMethodField()\n\n    class Meta(MovieListSerializer.Meta):\n        fields = MovieListSerializer.Meta.fields + [\n            \'cast_members\',\n            \'created_at\',\n            \'updated_at\',\n            \'my_rating\',\n        ]\n\n    def get_my_rating(self, obj):\n        user = self._user()\n\n        if user is None:\n            return None\n\n        rating = obj.ratings.filter(\n            user=user\n        ).first()\n\n        if rating is None:\n            return None\n\n        return {\n            \'score\': rating.score,\n            \'review\': rating.review,\n        }\n\n\nclass MovieWriteSerializer(serializers.ModelSerializer):\n    """\n    Serializer used by authenticated users to create and update\n    their own uploaded movies.\n\n    The owner is NOT supplied by the frontend.\n    The view will automatically assign request.user as the owner.\n    """\n\n    genre_ids = serializers.PrimaryKeyRelatedField(\n        source=\'genres\',\n        queryset=Genre.objects.all(),\n        many=True,\n        required=False\n    )\n\n    director_id = serializers.PrimaryKeyRelatedField(\n        source=\'director\',\n        queryset=Person.objects.all(),\n        required=False,\n        allow_null=True\n    )\n\n    video_file = serializers.FileField(\n        required=False,\n        allow_null=True\n    )\n\n    # Set instead of video_file when the browser has already uploaded the\n    # video straight to B2 via a presigned URL (see presign.py) - avoids\n    # sending the file through Django at all for large movie files.\n    video_file_key = serializers.CharField(\n        required=False,\n        allow_null=True,\n        write_only=True,\n    )\n\n    poster_image = serializers.ImageField(\n        required=False,\n        allow_null=True\n    )\n\n    visibility = serializers.ChoiceField(\n        choices=Movie.VISIBILITY_CHOICES,\n        required=False,\n        default=Movie.VISIBILITY_PRIVATE\n    )\n\n    class Meta:\n        model = Movie\n\n        fields = [\n            \'id\',\n            \'title\',\n            \'description\',\n            \'release_date\',\n            \'poster_url\',\n            \'poster_image\',\n            \'backdrop_url\',\n            \'runtime_minutes\',\n            \'rating\',\n\n            # Uploaded video\n            \'video_file\',\n            \'video_file_key\',\n\n            # Private/public\n            \'visibility\',\n\n            # Relationships\n            \'genre_ids\',\n            \'director_id\',\n        ]\n\n        read_only_fields = [\n            \'id\',\n        ]\n\n    def validate(self, attrs):\n        # Uploading through Django (video_file) and uploading directly to\n        # B2 first (video_file_key) are mutually exclusive - never both.\n        if attrs.get(\'video_file\') and attrs.get(\'video_file_key\'):\n            raise serializers.ValidationError(\n                \'Provide either video_file or video_file_key, not both.\'\n            )\n        return attrs\n\n    def create(self, validated_data):\n        video_file_key = validated_data.pop(\'video_file_key\', None)\n        movie = super().create(validated_data)\n\n        if video_file_key:\n            # The file already exists in storage (the browser PUT it there\n            # directly) - just point this movie\'s field at it, no upload.\n            movie.video_file.name = video_file_key\n            movie.save(update_fields=[\'video_file\'])\n\n        return movie\n\n    def update(self, instance, validated_data):\n        video_file_key = validated_data.pop(\'video_file_key\', None)\n        movie = super().update(instance, validated_data)\n\n        if video_file_key:\n            movie.video_file.name = video_file_key\n            movie.save(update_fields=[\'video_file\'])\n\n        return movie'

FILES['frontend/lib/endpoints.ts'] = "import { api, buildQuery } from './api';\nimport type {\n  DashboardData,\n  Favorite,\n  Genre,\n  Movie,\n  Paginated,\n  Playlist,\n  PlaylistMovieEntry,\n  Rating,\n  User,\n  WatchedEntry,\n  WatchlistEntry,\n} from '@/types';\n\n// --- Auth ---\nexport const authApi = {\n  register: (data: { username: string; email: string; password: string; password_confirm: string }) =>\n    api.post<{ user: User; access: string; refresh: string }>('/auth/register/', data, { skipAuth: true }),\n\n  login: (data: { username: string; password: string }) =>\n    api.post<{ user: User; access: string; refresh: string }>('/auth/login/', data, { skipAuth: true }),\n\n  logout: (refresh: string) => api.post<void>('/auth/logout/', { refresh }),\n\n  me: () => api.get<User>('/auth/me/'),\n\n  updateProfile: (data: Partial<Pick<User, 'username' | 'email' | 'bio' | 'avatar_url'>>) =>\n    api.patch<User>('/auth/me/', data),\n\n  changePassword: (data: { old_password: string; new_password: string }) =>\n    api.post<void>('/auth/change-password/', data),\n\n  requestPasswordReset: (email: string) =>\n    api.post<{ detail: string }>('/auth/password-reset/', { email }, { skipAuth: true }),\n\n  confirmPasswordReset: (data: { uid: string; token: string; new_password: string }) =>\n    api.post<void>('/auth/password-reset/confirm/', data, { skipAuth: true }),\n};\n\n// --- Movies ---\nexport interface MovieFilters {\n  search?: string;\n  genre?: string;\n  year?: number;\n  min_rating?: number;\n  watched?: boolean;\n  ordering?: string;\n  page?: number;\n}\n\nexport const moviesApi = {\n  list: (filters: MovieFilters = {}) =>\n    api.get<Paginated<Movie>>(\n      `/movies/${buildQuery(filters as Record<string, string | number | boolean>)}`\n    ),\n\n  myMovies: (page = 1) =>\n  api.get<Paginated<Movie>>(`/movies/my/${buildQuery({ page })}`),\n\n  detail: (id: number) => api.get<Movie>(`/movies/${id}/`),\n\n  genres: () => api.get<Genre[]>('/movies/genres/'),\n\n  create: (data: FormData) =>\n    api.post<Movie>('/movies/', data),\n\n  update: (id: number, data: FormData) =>\n    api.patch<Movie>(`/movies/${id}/`, data),\n\n  remove: (id: number) =>\n    api.delete<void>(`/movies/${id}/`),\n\n  presignVideoUpload: (filename: string, contentType: string) =>\n    api.post<{ upload_url: string; key: string }>(\n      '/movies/presign-video-upload/',\n      { filename, content_type: contentType }\n    ),\n};\n\n// --- Playlists ---\nexport const playlistsApi = {\n  list: (page = 1) => api.get<Paginated<Playlist>>(`/playlists/${buildQuery({ page })}`),\n\n  detail: (id: number) => api.get<Playlist>(`/playlists/${id}/`),\n\n  publicDetail: (id: number) => api.get<Playlist>(`/public/playlists/${id}/`, { skipAuth: true }),\n\n  create: (data: { name: string; description: string; is_public: boolean }) =>\n    api.post<Playlist>('/playlists/', data),\n\n  update: (id: number, data: Partial<{ name: string; description: string; is_public: boolean }>) =>\n    api.patch<Playlist>(`/playlists/${id}/`, data),\n\n  remove: (id: number) => api.delete<void>(`/playlists/${id}/`),\n\n  addMovie: (playlistId: number, movieId: number) =>\n    api.post<PlaylistMovieEntry>(`/playlists/${playlistId}/movies/`, { movie_id: movieId }),\n\n  removeMovie: (playlistId: number, movieId: number) =>\n    api.delete<void>(`/playlists/${playlistId}/movies/${movieId}/`),\n\n  updateMovieEntry: (playlistId: number, movieId: number, data: { watched?: boolean; notes?: string }) =>\n    api.patch<PlaylistMovieEntry>(`/playlists/${playlistId}/movies/${movieId}/`, data),\n\n  reorder: (playlistId: number, movieIds: number[]) =>\n    api.patch<Playlist>(`/playlists/${playlistId}/reorder/`, { movie_ids: movieIds }),\n};\n\n// --- Library: favorites / watchlist / watched / ratings ---\nexport const libraryApi = {\n  dashboard: () => api.get<DashboardData>('/dashboard/'),\n\n  favorites: (page = 1) => api.get<Paginated<Favorite>>(`/favorites/${buildQuery({ page })}`),\n  addFavorite: (movieId: number) => api.post<Favorite>('/favorites/', { movie_id: movieId }),\n  removeFavorite: (movieId: number) => api.delete<void>(`/favorites/${movieId}/`),\n\n  watchlist: (page = 1) => api.get<Paginated<WatchlistEntry>>(`/watchlist/${buildQuery({ page })}`),\n  addToWatchlist: (movieId: number) => api.post<WatchlistEntry>('/watchlist/', { movie_id: movieId }),\n  removeFromWatchlist: (movieId: number) => api.delete<void>(`/watchlist/${movieId}/`),\n\n  watched: (page = 1) => api.get<Paginated<WatchedEntry>>(`/watched/${buildQuery({ page })}`),\n  markWatched: (movieId: number) => api.post<WatchedEntry>('/watched/', { movie_id: movieId }),\n  markUnwatched: (movieId: number) => api.delete<void>(`/watched/${movieId}/`),\n\n  ratings: () => api.get<Paginated<Rating>>('/ratings/'),\n  rateMovie: (movieId: number, data: { score: number; review?: string }) =>\n    api.put<Rating>(`/ratings/${movieId}/`, data),\n  removeRating: (movieId: number) => api.delete<void>(`/ratings/${movieId}/`),\n};\n"

def main():
    root = os.getcwd()
    if not os.path.isdir(os.path.join(root, 'backend')) or not os.path.isdir(os.path.join(root, 'frontend')):
        print('Error: run this script from the project root (must contain backend/ and frontend/ folders).')
        sys.exit(1)
    print('Backing up files that will be changed (.bak)...')
    for rel_path in FILES:
        full_path = os.path.join(root, rel_path)
        if os.path.exists(full_path):
            shutil.copyfile(full_path, full_path + '.bak')
    for rel_path, content in FILES.items():
        full_path = os.path.join(root, rel_path)
        os.makedirs(os.path.dirname(full_path), exist_ok=True)
        print(f'Writing {rel_path}...')
        with open(full_path, 'w', encoding='utf-8', newline='\n') as f:
            f.write(content)
    print()
    print('Done. Next: git add -A && git commit -m "Restore direct-to-B2 upload wiring" && git push')
    print()
    print('Backups of the original files were saved alongside them as *.bak')

if __name__ == '__main__':
    main()
